select to_regprocedure('public.video_finder_save_approved_youtube(uuid,text,text,integer)') is not null as rpc_exists;
select has_function_privilege('authenticated','public.video_finder_save_approved_youtube(uuid,text,text,integer)','EXECUTE') authenticated_can_execute,not has_function_privilege('anon','public.video_finder_save_approved_youtube(uuid,text,text,integer)','EXECUTE') anon_cannot_execute;
select 'protected_counts' check_name,(select count(*) from public.xp_ledger) xp_ledger,(select count(*) from public.enrollments) enrollments,(select count(*) from public.submissions) submissions,(select count(*) from public.certificates) certificates,(select count(*) from public.lesson_progress) lesson_progress;
select 'curriculum_status_post' check_name,md5(coalesce(string_agg(id::text||':'||status,E'\n' order by id),'')) status_hash from public.course_modules;
select not (pg_get_functiondef('public.video_finder_save_approved_youtube(uuid,text,text,integer)'::regprocedure) ilike any(array['%xp_ledger%','%lesson_progress%','%enrollments%','%submissions%','%certificates%'])) and pg_get_functiondef('public.video_finder_save_approved_youtube(uuid,text,text,integer)'::regprocedure) not ilike '%course_modules set status=%' protected_scope_clean;
